def run(args):
    clear_scene()
    created = []
    for idx, comp in enumerate(components):
        name = comp.get('name', f'obj{idx+1}')
        verts = [tuple(v) for v in comp.get('vertices', [])]
        faces = [tuple(f) for f in comp.get('faces', [])]
        obj = create_mesh(name, verts, faces)
        matrix = comp.get('matrix_world')
        if matrix:
            obj.matrix_world = Matrix(matrix)
        created.append(obj)
    if not args.skip_save and args.output_blend:
        bpy.ops.wm.save_as_mainfile(filepath=args.output_blend)
    return created

if __name__ == '__main__':
    _args = parse_args()
    run(_args)
